    if seat is None:
        return
    pos = seat.position
    vel = seat.linearVelocity
    vx = vel.x
    vy = vel.y
    target_y = 11.7
    target_x_min = 9.35
    target_x_max = 10.65

    # Check if in target zone
    if pos.y >= target_y and target_x_min <= pos.x <= target_x_max:
        return

    # Wind compensation and dynamic force adjustment
    wind_compensation = 2.5  # Adjusted based on observed wind strength
    fx_wind = -wind_compensation * vx

    # Pumping phase: below target y
    if pos.y < target_y:
        # Apply vertical force upward
        fy = 42.0
        # Apply horizontal force to counteract wind and start moving towards target x
        if pos.x < target_x_min:
            desired_fx = 42.0  # Push right
        elif pos.x > target_x_max:
            desired_fx = -42.0  # Push left
        else:
            desired_fx = 0.0
        fx = desired_fx + fx_wind
    else:
        # Apex phase: move horizontally into target x range
        if pos.x < target_x_min:
            desired_fx = 42.0  # Push right
        elif pos.x > target_x_max:
            desired_fx = -42.0  # Push left
        else:
            desired_fx = 0.0
        fx = desired_fx + fx_wind

    # Handle dead zone with adaptive impulses
    dead_zone_threshold = 0.05  # Reduced to ensure force delivery
    if abs(vx) < dead_zone_threshold:
        # Apply impulse to break dead zone every 5 steps
        if step_count % 5 == 0:
            if pos.x < target_x_min:
                impulse_x = 4.2
            elif pos.x > target_x_max:
                impulse_x = -4.2
            else:
                impulse_x = 0.0
            sandbox.apply_impulse_to_seat(impulse_x, 0)
